black_count = 0

# Iterate through all squares (i, j) where 1 <= i, j <= N
for i in range(1, N + 1):
    for j in range(1, N + 1):
        # Assuming (1,1) is black, black squares have i+j even.
        if (i + j) % 2 == 0:
            black_count += 1

print(f"Total number of black squares: {black_count}")

# Verification using the derived formula for odd N: (N^2 + 1) / 2
expected_count = (N * N + 1) // 2
print(f"Expected count based on formula (N^2 + 1)/2: {expected_count}")

if black_count == expected_count:
    print("Verification successful: Simulation matches formula.")
else:
    print("Verification failed: Mismatch found.")

